<?php
namespace App\Form\Admin\Clients;
use App\Application\Clients\ClientInlineContactData; use Symfony\Component\Form\AbstractType; use Symfony\Component\Form\Extension\Core\Type\{CheckboxType,CollectionType,DateType,EmailType,HiddenType,TextareaType,TextType}; use Symfony\Component\Form\FormBuilderInterface; use Symfony\Component\OptionsResolver\OptionsResolver;
final class ClientInlineContactEntryType extends AbstractType { public function buildForm(FormBuilderInterface $b,array $o):void{$b->add('id',HiddenType::class)->add('firstName',TextType::class,['label'=>'Nombre(s)'])->add('lastName',TextType::class,['label'=>'Apellidos','required'=>false])->add('personalEmail',EmailType::class,['label'=>'Correo personal','required'=>false])->add('businessEmail',EmailType::class,['label'=>'Correo laboral','required'=>false])->add('birthDate',DateType::class,['label'=>'Cumpleaños','required'=>false,'widget'=>'single_text','input'=>'datetime_immutable'])->add('department',TextType::class,['label'=>'Departamento','required'=>false])->add('jobTitle',TextType::class,['label'=>'Puesto','required'=>false])->add('workDays',TextType::class,['label'=>'Días de atención','required'=>false])->add('workHours',TextType::class,['label'=>'Horario','required'=>false])->add('notes',TextareaType::class,['label'=>'Notas','required'=>false,'attr'=>['rows'=>2]])->add('isPrimary',CheckboxType::class,['label'=>'Contacto principal','required'=>false])->add('canRequestProducts',CheckboxType::class,['label'=>'Puede solicitar productos','required'=>false])->add('phones',CollectionType::class,['label'=>'Teléfonos y fax','entry_type'=>ClientPhoneEntryType::class,'allow_add'=>true,'allow_delete'=>true,'by_reference'=>false,'prototype'=>true,'prototype_name'=>'__contact_phone__']);} public function configureOptions(OptionsResolver $r):void{$r->setDefaults(['data_class'=>ClientInlineContactData::class]);}}
